void BFSModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;
    GraphModuleUtils::GraphInput input;
    m_valid = GraphModuleUtils::parse(inputData, true, m_options, input);
    m_mathText = scene->addText(m_valid ? "BFS：按层扩展，节点在入队时标记访问" : "输入格式：n m src，随后输入 m 条边 u v");
    m_mathText->setFont(QFont("Consolas", 15, QFont::Bold));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(180, 18);
    if (!m_valid) return;
    m_n = input.n;
    m_m = input.m;
    m_src = input.src;
    for (const auto& edge : input.edges) {
        m_edgeList.push_back({edge.u, edge.v});
        m_weightedEdgeList.push_back({edge.u, edge.v, edge.w});
        if (m_options.directed) {
            int id = ++m_edgeCount;
            m_to[id] = edge.v;
            m_next[id] = m_head[edge.u];
            m_head[edge.u] = id;
        } else {
            int id = ++m_edgeCount;
            m_to[id] = edge.v;
            m_next[id] = m_head[edge.u];
            m_head[edge.u] = id;
            id = ++m_edgeCount;
            m_to[id] = edge.u;
            m_next[id] = m_head[edge.v];
            m_head[edge.v] = id;
        }
    }
    GraphRenderHelper::buildNodes(scene, m_nodes, m_n, QPointF(470, 170), m_n <= 8 ? 115 : 135);
    GraphRenderHelper::buildEdges(scene, m_nodes, m_edges, input.edges, m_options, input.weighted);
    int startX = std::max(140, 470 - m_n * 30);
    GraphRenderHelper::addLabel(scene, "queue", QPointF(35, 348));
    GraphRenderHelper::addLabel(scene, "dist", QPointF(35, 448));
    GraphRenderHelper::addLabel(scene, "parent", QPointF(35, 548));
    for (int i = 1; i <= m_n; ++i) {
        int x = startX + (i - 1) * 60;
        ArrayBlock* queueBlock = new ArrayBlock(i - 1, 0, QString("q[%1]").arg(i - 1));
        queueBlock->showValue = false;
        queueBlock->setPos(x, 365);
        scene->addItem(queueBlock);
        m_queueBlocks[i - 1] = queueBlock;
        ArrayBlock* distance = new ArrayBlock(i, 0, QString("d[%1]").arg(i));
        distance->showValue = false;
        distance->setPos(x, 465);
        scene->addItem(distance);
        m_distanceBlocks[i] = distance;
        m_distanceLabels[i] = GraphRenderHelper::addLabel(scene, "∞", QPointF(x + 16, 471));
        ArrayBlock* parent = new ArrayBlock(i, 0, QString("pre[%1]").arg(i));
        parent->showValue = false;
        parent->setPos(x, 565);
        scene->addItem(parent);
        m_parentBlocks[i] = parent;
        m_parentLabels[i] = GraphRenderHelper::addLabel(scene, "—", QPointF(x + 21, 571));
    }
    m_headPointer = new PointerBlock("head", QColor(45, 130, 210));
    m_tailPointer = new PointerBlock("tail", QColor(210, 95, 50));
    m_headPointer->setOpacity(0);
    m_tailPointer->setOpacity(0);
    scene->addItem(m_headPointer);
    scene->addItem(m_tailPointer);
}

