void IModule::detachAllEdges(std::vector<GraphNode*>& nodes, std::vector<GraphEdge*>& edges) {
    for (GraphEdge* edge : edges) {
        if (edge) edge->detach();
    }
    edges.clear();
    for (GraphNode* node : nodes) {
        if (node) node->removeAllEdges();
    }
    nodes.clear();
}

