void IModule::playPointerCrowd(std::vector<PointerBlock*> ptrs, ArrayBlock* anchor, int slot, int spacing) {
    if (!anchor) return;
    std::vector<PointerBlock*> active;
    for (auto* p : ptrs) if (p && p->opacity() > 0.05) active.push_back(p);
    if (active.empty()) return;
    int count = static_cast<int>(active.size());
    double baseX = anchor->pos().x() + spacing / 2.0;
    double y = anchor->pos().y() + 42;
    for (int i = 0; i < count; ++i) {
        PointerBlock* p = active[i];
        double offsetX = 0;
        if (count == 2) offsetX = (i == 0) ? -15 : 15;
        else if (count == 3) offsetX = (i - 1) * 20;
        else if (count > 3) offsetX = (i - count / 2.0 + 0.5) * 15;
        if (slot >= 0 && i == slot) offsetX = 0;
        QPointF targetPos(baseX + offsetX, y);
        if (m_animated) {
            QPropertyAnimation* anim = new QPropertyAnimation(p, "pos");
            anim->setEndValue(targetPos);
            anim->setDuration(380);
            anim->setEasingCurve(QEasingCurve::InOutQuad);
            anim->start(QAbstractAnimation::DeleteWhenStopped);
        } else {
            p->setPos(targetPos);
        }
    }
}

void IModule::playPointerCrowd(std::vector<PointerBlock*> ptrs, GraphNode* anchor, int slot) {
    if (!anchor) return;
    for (auto* p : ptrs) {
        if (!p) continue;
        p->setAnchorNode(anchor);
    }
    std::vector<PointerBlock*> active;
    for (auto* p : ptrs) if (p && p->opacity() > 0.05) active.push_back(p);
    if (active.empty()) return;
    int count = static_cast<int>(active.size());
    double spread = 16.0;
    for (int i = 0; i < count; ++i) {
        PointerBlock* p = active[i];
        double delta = (i - (count - 1) / 2.0) * spread;
        if (slot >= 0 && i == slot) delta = 0;
        QPointF targetPos(anchor->pos() + QPointF(30, 30) + QPointF(delta, 0));
        if (m_animated) {
            QPropertyAnimation* anim = new QPropertyAnimation(p, "pos");
            anim->setEndValue(targetPos);
            anim->setDuration(380);
            anim->setEasingCurve(QEasingCurve::InOutQuad);
            anim->start(QAbstractAnimation::DeleteWhenStopped);
        } else {
            p->setPos(targetPos);
        }
    }
}

