void IModule::playPointerArrange(std::vector<PointerBlock*> ptrs, std::vector<QGraphicsItem*> anchors, double yOffset) {
    std::map<QGraphicsItem*, std::vector<PointerBlock*>> groups;
    for (int i = 0; i < static_cast<int>(ptrs.size()) && i < static_cast<int>(anchors.size()); ++i) {
        PointerBlock* p = ptrs[i];
        if (!p || !anchors[i] || p->opacity() < 0.05) continue;
        groups[anchors[i]].push_back(p);
    }
    for (auto& pair : groups) {
        QGraphicsItem* anchor = pair.first;
        std::vector<PointerBlock*>& group = pair.second;
        int count = static_cast<int>(group.size());
        double baseX = anchor->pos().x() + 30.0;
        double y = anchor->pos().y() + yOffset;
        for (int i = 0; i < count; ++i) {
            PointerBlock* p = group[i];
            double offsetX = 0;
            if (count == 2) offsetX = (i == 0) ? -15 : 15;
            else if (count == 3) offsetX = (i - 1) * 20;
            else if (count > 3) offsetX = (i - count / 2.0 + 0.5) * 16;
            QPointF targetPos(baseX + offsetX, y);
            if (m_animated) {
                QPropertyAnimation* anim = new QPropertyAnimation(p, "pos");
                anim->setEndValue(targetPos);
                anim->setDuration(380);
                anim->setEasingCurve(QEasingCurve::InOutQuad);
                anim->start(QAbstractAnimation::DeleteWhenStopped);
            } else {
                p->setPos(targetPos);
            }
        }
    }
}

