            m_frames.push_back({ActionType::SEG_OP_START, 1, op.l, op.r, static_cast<int>(op.k), {},
                                QString("执行区间乘：updateMul(%1, %2, %3)").arg(op.l).arg(op.r).arg(op.k),
                                QString("op = 1 → st.updateMul(%1, %2, %3)").arg(op.l).arg(op.r).arg(op.k)});
