            m_frames.push_back({ActionType::SEG_OP_START, 1, op.l, op.r, static_cast<int>(op.k), {},
                                QString("执行区间加：updateAdd(%1, %2, %3)").arg(op.l).arg(op.r).arg(op.k),
                                QString("op = 2 → st.updateAdd(%1, %2, %3)").arg(op.l).arg(op.r).arg(op.k)});
