QPropertyAnimation* IModule::acquireAnim(QObject* target, const char* property, int duration, const QEasingCurve& curve) {
    if (!target) return nullptr;
    auto key = std::make_pair(QPointer<QObject>(target), QString(property));
    auto it = m_animRegistry.find(key);
    QPropertyAnimation* anim = nullptr;
    if (it != m_animRegistry.end() && it->second) {
        anim = it->second;
    } else {
        anim = new QPropertyAnimation(target, property, this);
        m_animRegistry[key] = anim;
    }
    anim->stop();
    anim->setDuration(duration);
    anim->setEasingCurve(curve);
    return anim;
}

void IModule::releaseAnim(QObject* target, const char* property) {
    auto key = std::make_pair(QPointer<QObject>(target), QString(property));
    auto it = m_animRegistry.find(key);
    if (it == m_animRegistry.end()) return;
    if (it->second) {
        it->second->stop();
        delete it->second;
    }
    m_animRegistry.erase(it);
}

void IModule::stopAnimFor(QObject* target) {
    if (!target) return;
    std::vector<std::pair<QPointer<QObject>, QString>> dead;
    for (auto& kv : m_animRegistry) {
        if (kv.first.data() != target) continue;
        if (kv.second) kv.second->stop();
        dead.push_back(kv.first);
    }
    for (auto& key : dead) {
        auto it = m_animRegistry.find(key);
        if (it == m_animRegistry.end()) continue;
        if (it->second) delete it->second;
        m_animRegistry.erase(it);
    }
}

void IModule::stopAllAnims() {
    for (auto& kv : m_animRegistry) {
        if (kv.second) kv.second->stop();
    }
}

static std::vector<NodeInfo> buildTopology(int node, int l, int r, const QPointF& center, double dx, double dy) {
    std::vector<NodeInfo> result;
    NodeInfo info;
    info.node = node;
    info.l = l;
    info.r = r;
    info.pos = center;
    result.push_back(info);
    if (l == r) return result;
    int mid = (l + r) >> 1;
    std::vector<NodeInfo> left = buildTopology(ls(node), l, mid, center + QPointF(-dx, dy), dx / 2.0, dy);
    std::vector<NodeInfo> right = buildTopology(rs(node), mid + 1, r, center + QPointF(dx, dy), dx / 2.0, dy);
    result.insert(result.end(), left.begin(), left.end());
    result.insert(result.end(), right.begin(), right.end());
    return result;
}

static int treeDepth(int n) {
    if (n <= 0) return 1;
    int depth = 1;
    int span = n;
    while (span > 1) {
        span = (span + 1) / 2;
        ++depth;
    }
    return depth;
}

static std::vector<int> collectNodeIds(int node, int l, int r) {
    std::vector<int> ids;
    ids.push_back(node);
    if (l == r) return ids;
    int mid = (l + r) >> 1;
    std::vector<int> left = collectNodeIds(ls(node), l, mid);
    std::vector<int> right = collectNodeIds(rs(node), mid + 1, r);
    ids.insert(ids.end(), left.begin(), left.end());
    ids.insert(ids.end(), right.begin(), right.end());
    std::sort(ids.begin(), ids.end());
    return ids;
}

