void IModule::playRowShift(std::vector<QGraphicsItem*> items, QPointF delta, int duration) {
    if (items.empty()) return;
    if (!m_animated) {
        for (QGraphicsItem* item : items) {
            if (!item) continue;
            stopAnimFor(item->parentObject());
            item->setPos(item->pos() + delta);
        }
        return;
    }
    for (QGraphicsItem* item : items) {
        if (!item) continue;
        QPropertyAnimation* anim = acquireAnim(item->parentObject(), "pos", duration, QEasingCurve::InOutCubic);
        if (!anim) continue;
        anim->setStartValue(item->pos());
        anim->setEndValue(item->pos() + delta);
        anim->start();
    }
}

