}

void IModule::playRowShift(std::vector<QGraphicsItem*> items, QPointF delta, int duration) {
    if (items.empty()) return;
    std::vector<QPointF> starts;
    for (QGraphicsItem* item : items) {
        if (!item) continue;
        starts.push_back(item->pos());
    }
    if (!m_animated) {
        for (QGraphicsItem* item : items) {
            if (!item) continue;
            item->setPos(item->pos() + delta);
        }
        return;
    }
    QPointer<QVariantAnimation> anim = new QVariantAnimation(this);
    anim->setDuration(duration);
    anim->setStartValue(0.0);
    anim->setEndValue(1.0);
    anim->setEasingCurve(QEasingCurve::InOutCubic);
    QObject::connect(anim.data(), &QVariantAnimation::valueChanged, [items, starts, delta](const QVariant& progress) {
        qreal t = progress.toReal();
        for (size_t i = 0; i < items.size(); ++i) {
            if (!items[i]) continue;
            QPointF s = starts[i];
            items[i]->setPos(s.x() + delta.x() * t, s.y() + delta.y() * t);
        }
    });
    anim->start(QAbstractAnimation::DeleteWhenStopped);
}

