QPropertyAnimation* IModule::makeAnim(QObject* target, const char* property) {
    if (!target) return nullptr;
    auto key = std::make_pair(QPointer<QObject>(target), QString(property));
    static std::map<std::pair<QPointer<QObject>, QString>, QPropertyAnimation*> s_global;
    auto it = s_global.find(key);
    if (it != s_global.end() && it->second) {
        it->second->stop();
        return it->second;
    }
    QPropertyAnimation* anim = new QPropertyAnimation(target, QByteArray(property));
    s_global[key] = anim;
    m_ownedAnims.push_back(QPointer<QPropertyAnimation>(anim));
    return anim;
}

