            }
            node->update();
            continue;
        }
        GraphEdge* edge = qgraphicsitem_cast<GraphEdge*>(item);
        if (edge) {
            QString row = editableRowFor(edge);
            if (row.isEmpty()) continue;
            int value = edge->weight;
            if (EditableModel::instance().getValue(liveScope(), row, edge->weight, value)) {
