void FenwickTreeModule::refreshCoverLines() {
    if (!m_scene) return;
    for (QGraphicsLineItem* line : m_coverLines) {
        if (!line) continue;
        if (line->scene()) line->scene()->removeItem(line);
        delete line;
    }
    m_coverLines.clear();
    if (!m_valid) return;

    const double cellH = 40.0;
    for (int i = 1; i <= m_n; ++i) {
        ArrayBlock* t = tBlock(i);
        if (!t) continue;
        int len = lowbit(i);
        int left = i - len + 1;
        ArrayBlock* aLeft = aBlock(left);
        ArrayBlock* aRight = aBlock(i);
        if (!aLeft || !aRight) continue;

        QPointF apex(t->pos().x() + m_cellW / 2.0, t->pos().y());
        QPointF baseLeft(aLeft->pos().x() + m_cellW / 2.0, aLeft->pos().y() + cellH);
        QPointF baseRight(aRight->pos().x() + m_cellW / 2.0, aRight->pos().y() + cellH);

        for (int j = left; j <= i; ++j) {
            ArrayBlock* a = aBlock(j);
            if (!a) continue;
            QPointF base(a->pos().x() + m_cellW / 2.0, a->pos().y() + cellH);
            QGraphicsLineItem* line = m_scene->addLine(apex, base);
            line->setPen(QPen(QColor(kFtLink.red(), kFtLink.green(), kFtLink.blue(), 120), 1.5));
            line->setZValue(-2);
            m_coverLines.push_back(line);
        }

        QPointF baseY = baseLeft + QPointF(0, 8);
        QGraphicsLineItem* base = m_scene->addLine(baseY, baseRight + QPointF(0, 8));
        base->setPen(QPen(QColor(kFtLink.red(), kFtLink.green(), kFtLink.blue(), 170), 1.8));
        base->setZValue(-2);
        m_coverLines.push_back(base);
    }
}

