    m_frames.push_back({ActionType::TD_RESET, 0, 0, 0, 0, {}, "第一轮 DFS：从根出发维护 dep[] 与最深点 c", "dep[v] = dep[u] + 1"});

    std::map<int, std::vector<int>> undirected;
