void SandboxMatrixModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    const bool shapeOverridden = m_shapeOverridden;
    const bool sizeOverridden = m_sizeOverridden;
    const bool cellOverridden = m_cellOverridden;
    const int keptShape = m_shapeIndex;
    const int keptRows = m_rows;
    const int keptCols = m_cols;
    const int keptCell = m_cell;
    reset();
    m_scene = scene;
    m_shapeOverridden = shapeOverridden;
    m_sizeOverridden = sizeOverridden;
    m_cellOverridden = cellOverridden;

    std::vector<QPair<QString, QString>> kv;
    parseKeyValues(inputData, kv);
    int rows = 3;
    int cols = 3;
    int shapeIndex = 0;
    int cell = 52;
    for (const auto& pair : kv) {
        if (pair.first == "rows") rows = pair.second.toInt();
        else if (pair.first == "cols") cols = pair.second.toInt();
        else if (pair.first == "cell") cell = pair.second.toInt();
        else if (pair.first == "type") {
            const QString t = pair.second.trimmed().toLower();
            if (t == "determinant") shapeIndex = 1;
            else if (t == "table") shapeIndex = 2;
        }
    }
    if (rows < 1 || rows > 8 || cols < 1 || cols > 8) return;
    if (!m_shapeOverridden) m_shapeIndex = shapeIndex;
    else m_shapeIndex = keptShape;
    if (!m_sizeOverridden) {
        m_rows = rows;
        m_cols = cols;
    } else {
        m_rows = keptRows;
        m_cols = keptCols;
    }
    if (!m_cellOverridden) m_cell = qBound(34, cell, 80);
    else m_cell = keptCell;
    rebuildMatrix(m_rows, m_cols);

