std::vector<AnimFrame> ExgcdModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;

    m_frames.push_back({ActionType::EX_RESET, 0, 0, 0, 0, {},
                        QString("开始递归：exgcd(%1, %2)").arg(m_a).arg(m_b),
                        QString("目标是求出 x, y 使 a·x + b·y = gcd(a, b)")});

    const int depth = static_cast<int>(m_levels.size());
    if (depth == 0) return m_frames;

    for (int d = 0; d < depth; ++d) {
        const Level& lv = m_levels[d];
        m_frames.push_back({ActionType::EX_RECURSE, d, static_cast<int>(lv.a), static_cast<int>(lv.b), 0, {},
                            QString("第 %1 层：exgcd(%2, %3)").arg(d + 1).arg(lv.a).arg(lv.b),
                            lv.b == 0
                                ? QString("b = 0，递归到底")
                                : QString("因为 %1 ≠ 0，继续递归 exgcd(%2, %1 %% %2)").arg(lv.b).arg(lv.a)});
    }

    const int base = depth - 1;
    m_frames.push_back({ActionType::EX_BASE, base, static_cast<int>(m_levels[base].a), 1, 0, {},
                        QString("第 %1 层到达边界：b = 0，此时 x = 1, y = 0").arg(base + 1),
                        QString("b = 0 ⇒ x = 1, y = 0")});

    long long x = 1;
    long long y = 0;
    m_frames.push_back({ActionType::EX_BACKTRACE, base, static_cast<int>(m_levels[base].a),
                        static_cast<int>(x), static_cast<int>(y), {},
                        QString("第 %1 层：x = 1, y = 0").arg(base + 1),
                        QString("边界层 x = 1, y = 0")});

    for (int d = base - 1; d >= 0; --d) {
        const long long q = m_levels[d].a / m_levels[d].b;
        const long long newX = y;
        const long long newY = x - q * y;
        m_frames.push_back({ActionType::EX_BACKTRACE, d, static_cast<int>(m_levels[d].a),
                            static_cast<int>(newX), static_cast<int>(newY), {},
                            QString("回溯到第 %1 层：x = y' = %2，y = x' - (a/b)·y' = %3 - %4·%2 = %5")
                                .arg(d + 1).arg(newX).arg(x).arg(q).arg(y).arg(newY),
                            QString("x = y', y = x' - (a/b)·y'")});
        x = newX;
        y = newY;
    }

    m_frames.push_back({ActionType::EX_DONE, static_cast<int>(x), static_cast<int>(y), 0, 0, {},
                        QString("最终结果：%1·(%2) + %3·(%4) = gcd(%1, %3) = %5")
                            .arg(m_a).arg(x).arg(m_b).arg(y).arg(m_a),
                        QString("a·x + b·y = gcd(a, b)")});
    return m_frames;
}

struct HuffNode {
    int id = 0;
    long long weight = 0;
    int left = -1;
    int right = -1;
    int parent = -1;
    GraphNode* item = nullptr;
    int depth = 0;
};

HuffNode* nodeAt(int id);
void layoutForest();
void layoutTree();
std::vector<int> rootIds() const;

std::vector<int> HuffmanTreeModule::rootIds() const {
    std::vector<int> roots;
    for (const HuffNode& node : m_nodes) {
        if (node.parent < 0) roots.push_back(node.id);
    }
    return roots;
}

void HuffmanTreeModule::layoutForest() {
    const std::vector<int> roots = rootIds();
    const double startX = 180.0;
    const double gap = 118.0;
    const double y = 560.0;
    for (size_t i = 0; i < roots.size(); ++i) {
        HuffNode* node = nodeAt(roots[i]);
        if (!node || !node->item) continue;
        node->item->setPos(startX + static_cast<double>(i) * gap, y);
    }
}

void HuffmanTreeModule::layoutTree() {
    const int count = static_cast<int>(m_nodes.size());
    if (count == 0) return;
    std::vector<int> depth(count, 0);
    int maxDepth = 0;
    for (int i = 0; i < count; ++i) {
        if (m_nodes[i].parent < 0) continue;
        depth[i] = depth[m_nodes[i].parent] + 1;
        maxDepth = qMax(maxDepth, depth[i]);
    }
    std::vector<int> levelCount(maxDepth + 1, 0);
    for (int i = 0; i < count; ++i) ++levelCount[depth[i]];
    std::vector<int> levelIndex(maxDepth + 1, 0);
    const double levelGap = 92.0;
    const double leafGap = 108.0;
    const double centerX = 470.0;
    for (int i = 0; i < count; ++i) {
        const int d = depth[i];
        const double span = levelCount[d] * leafGap;
        const double x = centerX - span / 2.0 + levelIndex[d] * leafGap + leafGap / 2.0;
        const double y = 120.0 + d * levelGap;
        ++levelIndex[d];
        if (m_nodes[i].item) m_nodes[i].item->setPos(x, y);
    }
}

