void HuffmanTreeModule::computeLayout() {
    for (auto& kv : m_treeNodes) {
        HuffNode* node = nodeAt(kv.first);
        if (!node) continue;
        node->level = 0;
    }
    for (auto& kv : m_treeNodes) {
        HuffNode* node = nodeAt(kv.first);
        if (!node || node->parent < 0) continue;
        HuffNode* p = nodeAt(node->parent);
        if (p) node->level = p->level + 1;
    }

    int minLevel = 0, maxLevel = 0;
    bool first = true;
    for (auto& kv : m_treeNodes) {
        HuffNode* node = nodeAt(kv.first);
        if (!node) continue;
        if (first) {
            minLevel = maxLevel = node->level;
            first = false;
        } else {
            minLevel = qMin(minLevel, node->level);
            maxLevel = qMax(maxLevel, node->level);
        }
    }
    m_levelMin = minLevel;
    m_levelMax = maxLevel;

    std::vector<std::vector<int>> rows(maxLevel - minLevel + 1);
    for (auto& kv : m_treeNodes) {
        HuffNode* node = nodeAt(kv.first);
        if (!node) continue;
        rows[node->level - minLevel].push_back(node->id);
    }

    for (auto& row : rows) {
        std::sort(row.begin(), row.end(), [this](int a, int b) {
            const HuffNode* na = nodeAt(a);
            const HuffNode* nb = nodeAt(b);
            if (!na || !nb) return a < b;
            if (na->weight != nb->weight) return na->weight < nb->weight;
            return a < b;
        });
    }

    m_nextPositions.clear();
    for (size_t r = 0; r < rows.size(); ++r) {
        const double y = kTreeBottom - static_cast<double>(r) * kLevelH;
        const std::vector<int>& row = rows[r];
        const double rowSpan = qMax(1, static_cast<int>(row.size())) * kBaseGap;
        const double left = kTreeCenterX - rowSpan / 2.0 + kBaseGap / 2.0;
        for (size_t k = 0; k < row.size(); ++k) {
            m_nextPositions[row[k]] = QPointF(left + static_cast<double>(k) * kBaseGap, y);
        }
    }
}

