        rowX[r] = kTreeCenterX - rowWidth[r] / 2.0 + kBaseGap / 2.0;
        for (size_t k = 0; k < rows[r].size(); ++k) {
            const int id = rows[r][k];
            m_nextPositions[id] = QPointF(rowX[r] + static_cast<double>(k) * kBaseGap,
                                         kTreeBottom - static_cast<double>(r) * kLevelH);
        }
    }

    for (int pass = 0; pass < 3; ++pass) {
        for (size_t r = 0; r < rows.size(); ++r) {
            for (int id : rows[r]) {
                HuffNode* node = nodeAt(id);
                if (!node) continue;
                const double selfX = m_nextPositions[id].x();
                const double leftX = (node->left >= 0 && m_nextPositions.count(node->left))
                                         ? m_nextPositions[node->left].x() : selfX;
                const double rightX = (node->right >= 0 && m_nextPositions.count(node->right))
                                          ? m_nextPositions[node->right].x() : selfX;
                const double midX = (leftX + rightX) / 2.0;
                const double shifted = selfX + (midX - selfX) * 0.6;
                m_nextPositions[id] = QPointF(shifted, m_nextPositions[id].y());
            }
        }
    }
}

