void HuffmanTreeModule::simulateLayout() {
    const int count = static_cast<int>(m_nodes.size());
    if (count == 0) return;

    std::map<int, int> levels;
    std::map<int, int> cols;
    for (int i = 0; i < count; ++i) {
        levels[i] = 0;
        cols[i] = i;
    }

    std::vector<int> leaves;
    for (int i = 0; i < count; ++i) {
        if (m_nodes[i].original) leaves.push_back(i);
    }
    std::sort(leaves.begin(), leaves.end(), [this](int a, int b) {
        if (m_nodes[a].weight != m_nodes[b].weight) return m_nodes[a].weight < m_nodes[b].weight;
        return a < b;
    });
    for (size_t k = 0; k < leaves.size(); ++k) {
        cols[leaves[k]] = static_cast<int>(k);
    }
    m_sortedLeaves = leaves;

    auto shiftSubtree = [&](int root, int delta) {
        if (delta == 0) return;
        std::vector<int> stack;
        stack.push_back(root);
        while (!stack.empty()) {
            const int id = stack.back();
            stack.pop_back();
            levels[id] += delta;
            const HuffmanNodeData* node = nodeAt(id);
            if (!node) continue;
            if (node->left >= 0) stack.push_back(node->left);
            if (node->right >= 0) stack.push_back(node->right);
        }
    };

    for (size_t s = 0; s < m_plan.size(); ++s) {
        HuffmanMergeStep& step = m_plan[s];
        const int a = step.a;
        const int b = step.b;
        const int parent = step.parent;

        step.liftRows = levels;
        step.liftCols = cols;

        const int la = levels[a];
        const int lb = levels[b];
        const int base = qMax(la, lb);

        if (la != lb) {
            if (la < lb) shiftSubtree(a, lb - la);
            else shiftSubtree(b, la - lb);
        }
        levels[a] = base;
        levels[b] = base;
        levels[parent] = base + 1;

        step.rows = levels;
        step.cols = cols;
    }
}

void HuffmanTreeModule::simulateLayout() {
    const int count = static_cast<int>(m_nodes.size());
